    defer rows.Close()
    result := []map[string]any{}
    for rows.Next() {
        var evidence, origin, relation, artifact, root, relative, actor, at string
        if err := rows.Scan(&evidence,&origin,&relation,&artifact,&root,&relative,&actor,&at); err != nil { t.Fatal(err) }
